      "category": "network_architecture",
      "rationale": "Normalize only the GRU candidate-state preactivation with learned LayerNorm before tanh, preserving reset/update gate equations, hidden width, depth, embeddings, readout, scoring, loss and optimizer. Each category retains one model checkpoint containing its normalization parameters. The generated predictor already imports GRU4RecModel from train.py, so it automatically constructs the matching architecture.",
      "edits": [
        {
          "find": "class GRU4RecModel(nn.Module):",
          "replace": "@torch.jit.script
def _candidate_normalized_gru_layer(projected: torch.Tensor, hidden: torch.Tensor,
                                    weight_hh: torch.Tensor, bias_hh: torch.Tensor,
                                    norm_weight: torch.Tensor, norm_bias: torch.Tensor,
                                    eps: float):
    outputs = torch.jit.annotate(list[torch.Tensor], [])
    for input_step in projected.unbind(1):
        input_reset, input_update, input_candidate = input_step.chunk(3, dim=-1)
        recurrent = torch.nn.functional.linear(hidden, weight_hh, bias_hh)
        hidden_reset, hidden_update, hidden_candidate = recurrent.chunk(3, dim=-1)
        reset = torch.sigmoid(input_reset + hidden_reset)
        update = torch.sigmoid(input_update + hidden_update)
        candidate_preactivation = input_candidate + reset * hidden_candidate
        candidate = torch.tanh(torch.nn.functional.layer_norm(
            candidate_preactivation, [hidden.size(-1)], norm_weight, norm_bias, eps
        ))
        hidden = candidate + update * (hidden - candidate)
        outputs.append(hidden)
    return torch.stack(outputs, dim=1), hidden


class CandidateNormalizedGRU(nn.GRU):
    def __init__(self, input_size: int, hidden_size: int, num_layers: int = 1,
                 batch_first: bool = True, dropout: float = 0.0):
        super().__init__(input_size, hidden_size, num_layers=num_layers,
                         batch_first=batch_first, dropout=dropout)
        self.candidate_norms = nn.ModuleList([
            nn.LayerNorm(hidden_size) for _ in range(num_layers)
        ])

    def forward(self, input: torch.Tensor, hx: torch.Tensor | None = None):
        out = input if self.batch_first else input.transpose(0, 1)
        if hx is None:
            hx = out.new_zeros(self.num_layers, out.size(0), self.hidden_size)
        final_states = []
        for layer, norm in enumerate(self.candidate_norms):
            projected = torch.nn.functional.linear(
                out, getattr(self, f'weight_ih_l{layer}'),
                getattr(self, f'bias_ih_l{layer}')
            )
            out, hidden = _candidate_normalized_gru_layer(
                projected, hx[layer], getattr(self, f'weight_hh_l{layer}'),
                getattr(self, f'bias_hh_l{layer}'), norm.weight, norm.bias, norm.eps
            )
            final_states.append(hidden)
            if layer + 1 < self.num_layers and self.dropout > 0.0:
                out = torch.nn.functional.dropout(
                    out, p=self.dropout, training=self.training
                )
        if not self.batch_first:
            out = out.transpose(0, 1)
        return out, torch.stack(final_states, dim=0)


class GRU4RecModel(nn.Module):"
